CREATE OR REPLACE FUNCTION public.yorisou_account_deletion_verify_database(p_owner_account_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tables text[] := array[
    'yorisou_test_results','yorisou_ai_reflections','yorisou_ai_runs',
    'yorisou_daily_state_records','yorisou_values_assessments',
    'yorisou_private_check_in_plans','yorisou_private_memory_items','yorisou_private_recommendations',
    'yorisou_experience_cards','yorisou_recommendation_sets','yorisou_recommendation_actions',
    'yorisou_canonical_recommendation_sets','yorisou_canonical_recommendation_items',
    'yorisou_canonical_recommendation_actions','yorisou_assessment_attempts',
    'yorisou_account_deletion_requests'
  ];
  v_t text; v_n bigint; v_left jsonb := '{}'::jsonb;
begin
  foreach v_t in array v_tables loop
    if to_regclass('public.' || v_t) is null then continue; end if;
    execute format('select count(*) from public.%I where owner_account_id = $1', v_t)
      into v_n using p_owner_account_id;
    if v_n > 0 then v_left := v_left || jsonb_build_object(v_t, v_n); end if;
  end loop;

  -- Results may survive ONLY as content-free tombstones, and a tombstone has no owner by contract.
  if to_regclass('public.yorisou_assessment_results') is not null then
    select count(*) into v_n from public.yorisou_assessment_results
     where owner_account_id = p_owner_account_id;
    if v_n > 0 then v_left := v_left || jsonb_build_object('yorisou_assessment_results_owned', v_n); end if;
  end if;

  return v_left;   -- '{}' means clean
end;
$function$;

do $$ begin
  execute 'revoke all on function public.yorisou_account_deletion_verify_database(p_owner_account_id text) from public';
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on function public.yorisou_account_deletion_verify_database(p_owner_account_id text) from anon';
  end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'revoke all on function public.yorisou_account_deletion_verify_database(p_owner_account_id text) from authenticated';
  end if;
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    execute 'grant execute on function public.yorisou_account_deletion_verify_database(p_owner_account_id text) to service_role';
  end if;
end $$;

CREATE OR REPLACE FUNCTION public.yorisou_account_deletion_state_for_cursor(p_cursor text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case p_cursor
    when 'mutation_draining'  then 'identity_verified'
    when 'lock_marker'        then 'locked'
    when 'session_revocation' then 'locked'
    when 'database_erasure'   then 'database_erasure'
    when 'storage_erasure'    then 'storage_erasure'
    when 'identity_erasure'   then 'identity_erasure'
    when 'verifying'          then 'verifying'
    when 'finalizing'         then 'verifying'
    when 'completed'          then 'completed'
    else null
  end;
$function$;

do $$ begin
  execute 'revoke all on function public.yorisou_account_deletion_state_for_cursor(p_cursor text) from public';
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on function public.yorisou_account_deletion_state_for_cursor(p_cursor text) from anon';
  end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'revoke all on function public.yorisou_account_deletion_state_for_cursor(p_cursor text) from authenticated';
  end if;
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    execute 'grant execute on function public.yorisou_account_deletion_state_for_cursor(p_cursor text) to service_role';
  end if;
end $$;

CREATE OR REPLACE FUNCTION public.yorisou_account_deletion_stage_rank(p_stage text)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case p_stage
    when 'mutation_draining'  then 1
    when 'lock_marker'        then 2
    when 'session_revocation' then 3
    when 'database_erasure'   then 4
    when 'storage_erasure'    then 5
    when 'identity_erasure'   then 6
    when 'verifying'          then 7
    when 'finalizing'         then 8
    when 'completed'          then 9
    else null
  end;
$function$;

