CREATE OR REPLACE FUNCTION public.yorisou_account_deletion_require_executor(p_owner_account_id text, p_token_hash text, p_generation integer)
 RETURNS yorisou_account_deletion_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_job public.yorisou_account_deletion_jobs%rowtype;
begin
  select * into v_job from public.yorisou_account_deletion_jobs
   where owner_account_id = p_owner_account_id for update;
  if not found then raise exception 'account_deletion_job_not_found'; end if;

  if v_job.executor_token_hash is null or v_job.executor_token_hash <> p_token_hash then
    raise exception 'account_deletion_executor_not_owner';
  end if;
  if v_job.executor_generation <> p_generation then
    raise exception 'account_deletion_executor_stale_generation';
  end if;
  if v_job.executor_expires_at is null or v_job.executor_expires_at <= now() then
    raise exception 'account_deletion_executor_lease_expired';
  end if;
  return v_job;
end;
$function$;

do $$ begin
  execute 'revoke all on function public.yorisou_account_deletion_require_executor(p_owner_account_id text, p_token_hash text, p_generation integer) from public';
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on function public.yorisou_account_deletion_require_executor(p_owner_account_id text, p_token_hash text, p_generation integer) from anon';
  end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'revoke all on function public.yorisou_account_deletion_require_executor(p_owner_account_id text, p_token_hash text, p_generation integer) from authenticated';
  end if;
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    execute 'grant execute on function public.yorisou_account_deletion_require_executor(p_owner_account_id text, p_token_hash text, p_generation integer) to service_role';
  end if;
end $$;

CREATE OR REPLACE FUNCTION public.yorisou_account_deletion_record_retryable_error(p_owner_account_id text, p_token_hash text, p_generation integer, p_error_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_job public.yorisou_account_deletion_jobs%rowtype;
begin
  v_job := public.yorisou_account_deletion_require_executor(p_owner_account_id, p_token_hash, p_generation);

  update public.yorisou_account_deletion_jobs
     set state           = 'failed_retryable',
         last_error_code = left(coalesce(p_error_code, 'unknown'), 80),
         attempt_count   = attempt_count + 1,
         -- execution_cursor is NOT touched. That is the point.
         updated_at      = now()
   where id = v_job.id
  returning * into v_job;

  insert into public.yorisou_account_deletion_audit (job_id, stage, outcome, detail)
  values (v_job.id, coalesce(v_job.execution_cursor, 'unknown'), 'failed',
          jsonb_build_object('retryable', true, 'generation', p_generation));

  return jsonb_build_object(
    'cursor', v_job.execution_cursor,
    'attemptCount', v_job.attempt_count,
    'irreversible', v_job.irreversible_started_at is not null
  );
end;
$function$;

do $$ begin
  execute 'revoke all on function public.yorisou_account_deletion_record_retryable_error(p_owner_account_id text, p_token_hash text, p_generation integer, p_error_code text) from public';
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on function public.yorisou_account_deletion_record_retryable_error(p_owner_account_id text, p_token_hash text, p_generation integer, p_error_code text) from anon';
  end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'revoke all on function public.yorisou_account_deletion_record_retryable_error(p_owner_account_id text, p_token_hash text, p_generation integer, p_error_code text) from authenticated';
  end if;
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    execute 'grant execute on function public.yorisou_account_deletion_record_retryable_error(p_owner_account_id text, p_token_hash text, p_generation integer, p_error_code text) to service_role';
  end if;
end $$;

