CREATE OR REPLACE FUNCTION public.yorisou_account_deletion_manifest_put(p_owner_account_id text, p_token_hash text, p_generation integer, p_payload jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_job public.yorisou_account_deletion_jobs%rowtype;
begin
  v_job := public.yorisou_account_deletion_require_executor(p_owner_account_id, p_token_hash, p_generation);

  if v_job.irreversible_started_at is not null then
    raise exception 'account_deletion_manifest_frozen';
  end if;
  if p_payload is null or jsonb_typeof(p_payload) <> 'object' then
    raise exception 'account_deletion_manifest_invalid';
  end if;

  insert into public.yorisou_account_deletion_manifests (job_id, payload)
  values (v_job.id, p_payload)
  on conflict (job_id) do nothing;   -- immutable: a second write is a no-op, never an overwrite
  return true;
end;
$function$;

do $$ begin
  execute 'revoke all on function public.yorisou_account_deletion_manifest_put(p_owner_account_id text, p_token_hash text, p_generation integer, p_payload jsonb) from public';
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on function public.yorisou_account_deletion_manifest_put(p_owner_account_id text, p_token_hash text, p_generation integer, p_payload jsonb) from anon';
  end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'revoke all on function public.yorisou_account_deletion_manifest_put(p_owner_account_id text, p_token_hash text, p_generation integer, p_payload jsonb) from authenticated';
  end if;
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    execute 'grant execute on function public.yorisou_account_deletion_manifest_put(p_owner_account_id text, p_token_hash text, p_generation integer, p_payload jsonb) to service_role';
  end if;
end $$;

