CREATE OR REPLACE FUNCTION public.yorisou_account_deletion_finalize(p_owner_account_id text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid; v_state text; v_left jsonb;
begin
  select id, state into v_id, v_state from public.yorisou_account_deletion_jobs
   where owner_account_id = p_owner_account_id for update;
  if not found then raise exception 'account_deletion_job_not_found'; end if;
  if v_state <> 'verifying' then raise exception 'account_deletion_not_verifying'; end if;

  v_left := public.yorisou_account_deletion_verify_database(p_owner_account_id);
  if v_left <> '{}'::jsonb then
    update public.yorisou_account_deletion_jobs
       set state='failed_retryable', last_error_code='verification_residue',
           attempt_count=attempt_count+1, updated_at=now()
     where id = v_id;
    insert into public.yorisou_account_deletion_audit (job_id, stage, outcome, detail)
    values (v_id, 'verifying', 'failed', jsonb_build_object('residue', v_left));
    return false;
  end if;

  update public.yorisou_account_deletion_jobs
     set state='completed', owner_account_id=null, completed_at=now(), updated_at=now()
   where id = v_id;
  insert into public.yorisou_account_deletion_audit (job_id, stage, outcome)
  values (v_id, 'completed', 'ok');
  return true;
end;
$function$;

do $$ begin
  execute 'revoke all on function public.yorisou_account_deletion_finalize(p_owner_account_id text) from public';
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on function public.yorisou_account_deletion_finalize(p_owner_account_id text) from anon';
  end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'revoke all on function public.yorisou_account_deletion_finalize(p_owner_account_id text) from authenticated';
  end if;
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    execute 'grant execute on function public.yorisou_account_deletion_finalize(p_owner_account_id text) to service_role';
  end if;
end $$;

CREATE OR REPLACE FUNCTION public.yorisou_account_deletion_finalize_step(p_owner_account_id text, p_token_hash text, p_generation integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_job public.yorisou_account_deletion_jobs%rowtype; v_left jsonb;
begin
  v_job := public.yorisou_account_deletion_require_executor(p_owner_account_id, p_token_hash, p_generation);

  if v_job.execution_cursor is distinct from 'finalizing' then
    raise exception 'account_deletion_cursor_mismatch_expected_finalizing_actual_%',
      coalesce(v_job.execution_cursor, 'null');
  end if;

  v_left := public.yorisou_account_deletion_verify_database(p_owner_account_id);
  if v_left <> '{}'::jsonb then
    update public.yorisou_account_deletion_jobs
       set state='failed_retryable', last_error_code='verification_residue',
           attempt_count = attempt_count + 1, updated_at = now()
     where id = v_job.id;      -- cursor preserved: the retry re-runs finalizing, nothing earlier
    insert into public.yorisou_account_deletion_audit (job_id, stage, outcome, detail)
    values (v_job.id, 'finalizing', 'failed', jsonb_build_object('residue', v_left));
    return jsonb_build_object('completed', false, 'residue', v_left);
  end if;

  update public.yorisou_account_deletion_jobs
     set state = 'completed',
         execution_cursor = 'completed',
         owner_account_id = null,
         completed_at = now(),
         executor_token_hash = null,
         executor_expires_at = null,
         updated_at = now()
   where id = v_job.id;

  insert into public.yorisou_account_deletion_audit (job_id, stage, outcome)
  values (v_job.id, 'completed', 'ok');

  return jsonb_build_object('completed', true);
end;
$function$;

do $$ begin
  execute 'revoke all on function public.yorisou_account_deletion_finalize_step(p_owner_account_id text, p_token_hash text, p_generation integer) from public';
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on function public.yorisou_account_deletion_finalize_step(p_owner_account_id text, p_token_hash text, p_generation integer) from anon';
  end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'revoke all on function public.yorisou_account_deletion_finalize_step(p_owner_account_id text, p_token_hash text, p_generation integer) from authenticated';
  end if;
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    execute 'grant execute on function public.yorisou_account_deletion_finalize_step(p_owner_account_id text, p_token_hash text, p_generation integer) to service_role';
  end if;
end $$;

CREATE OR REPLACE FUNCTION public.yorisou_account_deletion_executor_renew(p_owner_account_id text, p_token_hash text, p_generation integer, p_ttl_seconds integer DEFAULT 90)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
