  execute 'revoke all on function public.yorisou_account_deletion_close_mutation_gate(p_owner_account_id text) from public';
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on function public.yorisou_account_deletion_close_mutation_gate(p_owner_account_id text) from anon';
  end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'revoke all on function public.yorisou_account_deletion_close_mutation_gate(p_owner_account_id text) from authenticated';
  end if;
