CREATE OR REPLACE FUNCTION public.yorisou_account_deletion_advance(p_owner_account_id text, p_to text, p_error_code text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid; v_from text; v_cursor text; v_irreversible timestamptz; v_ok boolean;
begin
  select id, state, execution_cursor, irreversible_started_at
    into v_id, v_from, v_cursor, v_irreversible
    from public.yorisou_account_deletion_jobs
   where owner_account_id = p_owner_account_id
   for update;
  if not found then raise exception 'account_deletion_job_not_found'; end if;

  -- The engine owns forward motion. Anything else is a bypass, and a bypass is how the invariants
  -- above become decorative.
  if v_cursor is not null
     and p_to not in ('failed_retryable','failed_terminal','cancelled','legal_hold') then
    raise exception 'account_deletion_advance_superseded_by_cursor';
  end if;

  if p_to = 'cancelled' and v_irreversible is not null then
    raise exception 'account_deletion_irreversible';
  end if;

  v_ok := case
    when p_to = 'identity_verified' then v_from in ('requested','failed_retryable')
    when p_to = 'locked'            then v_from in ('identity_verified','failed_retryable')
    when p_to = 'database_erasure'  then v_from in ('locked','failed_retryable','database_erasure')
    when p_to = 'storage_erasure'   then v_from in ('database_erasure','failed_retryable','storage_erasure')
    when p_to = 'identity_erasure'  then v_from in ('storage_erasure','failed_retryable','identity_erasure')
    when p_to = 'verifying'         then v_from in ('identity_erasure','failed_retryable','verifying')
    when p_to = 'failed_retryable'  then v_from not in ('completed','cancelled','failed_terminal','legal_hold')
    when p_to = 'failed_terminal'   then v_from not in ('completed','cancelled')
    when p_to = 'cancelled'         then v_from in ('requested','identity_verified')
    when p_to = 'legal_hold'        then v_from in ('requested','identity_verified','locked')
    else false
  end;

  if not v_ok then
    raise exception 'account_deletion_illegal_transition_%_to_%', v_from, p_to;
  end if;

  update public.yorisou_account_deletion_jobs
     set state           = p_to,
         verified_at     = case when p_to='identity_verified' then now() else verified_at end,
         locked_at       = case when p_to='locked'            then now() else locked_at   end,
         cancelled_at    = case when p_to='cancelled'         then now() else cancelled_at end,
         -- Reaching `identity_verified` is the moment the engine takes over, so the cursor is
         -- initialised here rather than on first claim. A job with a cursor is a job the engine owns.
         execution_cursor = case
           when p_to = 'identity_verified' then coalesce(execution_cursor, 'mutation_draining')
           else execution_cursor end,
         last_error_code = case when p_to like 'failed%' then left(coalesce(p_error_code,'unknown'), 80) else null end,
         attempt_count   = case when p_to like 'failed%' then attempt_count + 1 else attempt_count end,
         updated_at      = now()
   where id = v_id;

  insert into public.yorisou_account_deletion_audit (job_id, stage, outcome, detail)
  values (v_id, p_to, case when p_to like 'failed%' then 'failed' else 'ok' end,
          jsonb_build_object('from', v_from));
  return p_to;
end;
$function$;

do $$ begin
  execute 'revoke all on function public.yorisou_account_deletion_advance(p_owner_account_id text, p_to text, p_error_code text) from public';
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on function public.yorisou_account_deletion_advance(p_owner_account_id text, p_to text, p_error_code text) from anon';
  end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'revoke all on function public.yorisou_account_deletion_advance(p_owner_account_id text, p_to text, p_error_code text) from authenticated';
  end if;
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    execute 'grant execute on function public.yorisou_account_deletion_advance(p_owner_account_id text, p_to text, p_error_code text) to service_role';
  end if;
end $$;

CREATE OR REPLACE FUNCTION public.yorisou_account_deletion_terminal_deidentify(p_owner_account_id text, p_reason text DEFAULT 'manifest_missing_pre_irreversible'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_job public.yorisou_account_deletion_jobs%rowtype;
  v_now timestamptz := now();
  v_has_manifest boolean;
  v_claim_live boolean;
begin
  if p_owner_account_id is null or char_length(p_owner_account_id) = 0 then
    raise exception 'account_deletion_owner_required';
  end if;

  select * into v_job from public.yorisou_account_deletion_jobs
   where owner_account_id = p_owner_account_id
   for update;

  if not found then
    -- Idempotent: a job already de-identified no longer carries the id, so there is nothing to find
    -- and nothing to do. Reporting this as an error would make a safe repeat look like a fault.
    return jsonb_build_object('deidentified', false, 'outcome', 'absent_or_already_deidentified');
  end if;

  -- ── ELIGIBILITY. Every clause refuses a DIFFERENT way of getting this wrong. ──

  -- Only a terminal failure. A completed job has its own de-identification; anything live is work
  -- in progress and must keep the id every operation looks it up by.
  if v_job.state is distinct from 'failed_terminal' then
    raise exception 'terminal_deidentify_refused_state_%', v_job.state;
  end if;

  -- NOTHING MAY HAVE BEEN DESTROYED. Past the crossing, the job is the only record of what was
  -- erased and for whom; minimising it there would destroy the audit trail of a real deletion.
  if v_job.irreversible_started_at is not null then
    raise exception 'terminal_deidentify_refused_irreversible';
  end if;

  -- The cursor is the second, independent witness to the same question. `irreversible_started_at`
  -- is the recorded fact; a cursor at or past the crossing would contradict it, and a contradiction
  -- is not something to resolve in favour of deleting identity.
  if v_job.execution_cursor is not null
     and public.yorisou_account_deletion_stage_rank(v_job.execution_cursor)
         >= public.yorisou_account_deletion_irreversible_rank() then
    raise exception 'terminal_deidentify_refused_cursor_%', v_job.execution_cursor;
  end if;

  -- A frozen manifest means the job CAN still be resumed, so it must be — resuming is strictly
  -- better than minimising a failure that did not have to be final.
  select exists (select 1 from public.yorisou_account_deletion_manifests where job_id = v_job.id)
    into v_has_manifest;
  if v_has_manifest then
    raise exception 'terminal_deidentify_refused_manifest_present';
  end if;

  -- Someone may be driving it right now.
  v_claim_live := v_job.executor_token_hash is not null
                  and v_job.executor_expires_at is not null
                  and v_job.executor_expires_at > v_now;
  if v_claim_live then
    raise exception 'terminal_deidentify_refused_executor_held';
  end if;

  if p_reason is distinct from 'manifest_missing_pre_irreversible' then
    raise exception 'terminal_deidentify_refused_reason_%', coalesce(p_reason, 'null');
  end if;

  -- ── THE MINIMISATION ────────────────────────────────────────────────────────
  --
  -- The fingerprint stays: it is one-way, it is what the replay and authentication checks already
  -- consult, and it lets this failure still be recognised without naming anyone. `last_error_code`
  -- stays because a failure record that cannot say why it failed is not an audit record.
  update public.yorisou_account_deletion_jobs
     set owner_account_id = null,
         executor_token_hash = null,
         executor_expires_at = null,
         terminal_deidentified_at = v_now,
         terminal_deidentification_reason = p_reason,
         updated_at = v_now
   where id = v_job.id;

  insert into public.yorisou_account_deletion_audit (job_id, stage, outcome, detail)
  values (v_job.id, 'terminal_deidentified', 'ok',
          jsonb_build_object('reason', p_reason, 'from_state', v_job.state));

  return jsonb_build_object('deidentified', true, 'outcome', 'terminal_deidentified');
end;
$function$;

do $$ begin
  execute 'revoke all on function public.yorisou_account_deletion_terminal_deidentify(p_owner_account_id text, p_reason text) from public';
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on function public.yorisou_account_deletion_terminal_deidentify(p_owner_account_id text, p_reason text) from anon';
  end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'revoke all on function public.yorisou_account_deletion_terminal_deidentify(p_owner_account_id text, p_reason text) from authenticated';
  end if;
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    execute 'grant execute on function public.yorisou_account_deletion_terminal_deidentify(p_owner_account_id text, p_reason text) to service_role';
  end if;
end $$;

CREATE OR REPLACE FUNCTION public.yorisou_account_deletion_status(p_owner_account_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v jsonb;
begin
  select jsonb_build_object('state', state, 'requestedAt', requested_at, 'attemptCount', attempt_count,
                            'lastErrorCode', last_error_code, 'contractVersion', contract_version)
    into v from public.yorisou_account_deletion_jobs where owner_account_id = p_owner_account_id;
  if v is null then
    -- A completed job no longer carries the id; the fingerprint proves the deletion happened.
    select jsonb_build_object('state', state, 'completedAt', completed_at, 'contractVersion', contract_version)
      into v from public.yorisou_account_deletion_jobs
     where owner_fingerprint = public.yorisou_account_deletion_fingerprint(p_owner_account_id)
       and state = 'completed' limit 1;
  end if;
  return coalesce(v, jsonb_build_object('state', 'none'));
end;
$function$;

do $$ begin
  execute 'revoke all on function public.yorisou_account_deletion_status(p_owner_account_id text) from public';
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on function public.yorisou_account_deletion_status(p_owner_account_id text) from anon';
  end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'revoke all on function public.yorisou_account_deletion_status(p_owner_account_id text) from authenticated';
  end if;
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    execute 'grant execute on function public.yorisou_account_deletion_status(p_owner_account_id text) to service_role';
  end if;
end $$;

CREATE OR REPLACE FUNCTION public.yorisou_account_deletion_open(p_owner_account_id text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid; v_state text;
begin
  if p_owner_account_id is null or char_length(p_owner_account_id) = 0 then
    raise exception 'account_deletion_owner_required';
  end if;

  select id, state into v_id, v_state
    from public.yorisou_account_deletion_jobs
   where owner_account_id = p_owner_account_id
   for update;

  if found then
    if v_state = 'legal_hold'      then raise exception 'account_deletion_legal_hold'; end if;
    if v_state = 'failed_terminal' then raise exception 'account_deletion_failed_terminal'; end if;
    -- A cancelled job may be reopened; anything else in flight is simply returned.
    if v_state = 'cancelled' then
      update public.yorisou_account_deletion_jobs
         set state='requested', cancelled_at=null, last_error_code=null, updated_at=now()
       where id = v_id;
    end if;
    return v_id;
  end if;

  begin
    insert into public.yorisou_account_deletion_jobs (owner_account_id, owner_fingerprint)
    values (p_owner_account_id, public.yorisou_account_deletion_fingerprint(p_owner_account_id))
    returning id into v_id;

    insert into public.yorisou_account_deletion_audit (job_id, stage, outcome)
    values (v_id, 'requested', 'ok');
    return v_id;
  exception when unique_violation then
    -- The index serialized us. Re-read under a lock: by now the winner has committed, so this is a
    -- genuine read of their row and not a second guess at the race.
    select id, state into v_id, v_state
      from public.yorisou_account_deletion_jobs
     where owner_account_id = p_owner_account_id
     for update;

    if not found then
      -- A unique violation with no surviving row means the winner's transaction rolled back after
      -- claiming the key. Nothing can be returned honestly, and inventing a job would be worse.
      raise exception 'account_deletion_open_lost_race';
    end if;

    -- The refusals are not skipped just because we arrived here the hard way.
    if v_state = 'legal_hold'      then raise exception 'account_deletion_legal_hold'; end if;
    if v_state = 'failed_terminal' then raise exception 'account_deletion_failed_terminal'; end if;
    if v_state = 'cancelled' then
      update public.yorisou_account_deletion_jobs
         set state='requested', cancelled_at=null, last_error_code=null, updated_at=now()
       where id = v_id;
    end if;

    -- No second audit row. The winner already recorded `requested`; a duplicate would read as two
    -- people asking to be deleted.
    return v_id;
  end;
end;
$function$;

do $$ begin
  execute 'revoke all on function public.yorisou_account_deletion_open(p_owner_account_id text) from public';
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on function public.yorisou_account_deletion_open(p_owner_account_id text) from anon';
  end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'revoke all on function public.yorisou_account_deletion_open(p_owner_account_id text) from authenticated';
  end if;
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    execute 'grant execute on function public.yorisou_account_deletion_open(p_owner_account_id text) to service_role';
  end if;
end $$;

CREATE OR REPLACE FUNCTION public.yorisou_account_deletion_manifest_for_owner(p_owner_account_id text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select m.payload
    from public.yorisou_account_deletion_manifests m
    join public.yorisou_account_deletion_jobs j on j.id = m.job_id
   where j.owner_account_id = p_owner_account_id
      or j.owner_fingerprint = public.yorisou_account_deletion_fingerprint(p_owner_account_id)
   limit 1;
$function$;

do $$ begin
  execute 'revoke all on function public.yorisou_account_deletion_manifest_for_owner(p_owner_account_id text) from public';
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on function public.yorisou_account_deletion_manifest_for_owner(p_owner_account_id text) from anon';
  end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'revoke all on function public.yorisou_account_deletion_manifest_for_owner(p_owner_account_id text) from authenticated';
  end if;
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    execute 'grant execute on function public.yorisou_account_deletion_manifest_for_owner(p_owner_account_id text) to service_role';
  end if;
end $$;
